import{z as n,x as s,o,c as E,q as t,j as i,D as a,d as r,s as d,S as p}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"PD 分离","description":"","frontmatter":{"title":"PD 分离","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pd-disaggregation.md","filePath":"llm/pd-disaggregation.md","lastUpdated":1791413859000}'),c={name:"llm/pd-disaggregation.md"};function A(B,e,T,D,P,h){const l=s("Mermaid");return o(),E("div",null,[e[2]||(e[2]=t('<h1 id="pd-分离" tabindex="-1">PD 分离 <a class="header-anchor" href="#pd-分离" aria-label="Permalink to &quot;PD 分离&quot;">​</a></h1><div class="epigraph"><p>Prefill 偏计算、decode 偏带宽，绑在同一张 GPU 上会互相抢时间和并行策略；拆到不同池子，才能各自满足 TTFT 与 TPOT，并按阶段选硬件。</p><footer>—— Zhong et al., DistServe, OSDI 2024；Patel et al., Splitwise, ISCA 2024</footer></div><p>一次生成请求先经历 prefill：把整段提示并行算完，写出 KV，得到首 token（TTFT）；再经历 decode：逐步吐后续 token，每步时间构成 TPOT。Colocate 系统把两阶段编进同一连续批，长 prefill 插入时 decode 步被拉长，decode 占着 HBM 时 prefill 又凑不齐算力。并行策略也被耦合：为 TTFT 加的 <a href="/llm/infer-tp">张量并行</a> 可能伤害 decode 的 All-Reduce 账，为吞吐加的 <a href="/llm/infer-pp">流水线</a> 可能伤害单请求延迟。Zhong 等人的 DistServe 把两阶段拆到不同 GPU 实例，按 TTFT/TPOT 分别搜资源与并行，优化 goodput（满足双 SLO 的最大速率）。Patel 等人的 Splitwise 从表征出发做阶段拆分，并强调异构硬件与功耗：prompt 需要新卡的算力，generation 可以用更低功耗、更低成本的机器。本篇写为何拆、怎么分池，KV 怎么搬见 <a href="/llm/pd-kv-transfer">下一篇</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Prefill 在提示不算极短时接近 compute-bound：序列长，GEMM 能喂饱 Tensor Core。Decode 每步一个新 token，却要读全部权重与日益增长的 KV，接近 memory-bound。两者的最优 batch、最优并行、甚至最优 GPU 代数都不同。绑在一起时，调度只能优先其中一个 SLO，或靠超配同时满足两个。Chunked-prefill 加 piggyback 把长提示切开与 decode 拼批，能减轻 decode 被单次长 prefill 堵住，但 DistServe 指出干扰并未消除：块太小则 prefill 自己不饱和且与 decode 争用；块大到饱和则几乎拼不进 decode；prefill 还会重复扫 KV，多付内存访问。</p><p><span class="marginnote">术语翻译：TTFT（time to first token）是从按下回车到看见第一个字的等待时间；TPOT（time per output token）是之后每个字之间隔多久。聊天产品里前者决定「卡不卡」，后者决定「读起来顺不顺」——这正是本篇反复说的两个 SLO。</span></p><p><span class="marginnote">数字实例：设 TPOT 预算是 50 毫秒。colocate 系统里一条 8000 token 的长提示插进连续批，可能把那一步 decode 拖到几百毫秒，同批所有请求的 TPOT 齐刷刷超标；拆开后，长提示只在 P 池里拖长它自己的 TTFT，D 池的每一步仍在 50 毫秒内——干扰从「全场连坐」变成「谁的事谁背」。</span></p><p>并行耦合是第二层问题。Intra-op 降执行时间、要 NVLink；inter-op 扩速率、少降延迟。Colocate 实例只能选一套。拆开之后，prefill 实例可以按紧 TTFT 走更大 TP，decode 实例按 TPOT 与 KV 容量走复制或不同的 PP。</p><h3 id="goodput-不是吞吐" tabindex="-1">Goodput 不是吞吐 <a class="header-anchor" href="#goodput-不是吞吐" aria-label="Permalink to &quot;Goodput 不是吞吐&quot;">​</a></h3><p>吞吐可以靠牺牲延迟堆上去。DistServe 优化的是在 TTFT 与 TPOT <strong>同时</strong>满足（评测里对 \\(\\gt 90\\%\\) 请求达标）时，每 GPU 能吃的请求率。这个指标让「拆开之后多复制了一份权重」的代价可见：权重多占卡，但若干扰消失、并行更贴合，达标速率仍可升。论文报告在多种模型与聊天、编程助手、摘要负载上，相对当时 SOTA 可达约 7.4 倍请求率或约 12.6 倍更紧的 SLO。数字钉在他们的引擎与负载上，不是宇宙常数。</p><p><span class="marginnote">实例（instance）在 DistServe 里是「一份完整模型权重对应的资源」，内部可以有多卡模型并行。拆分后有 prefill 实例与 decoding 实例，权重至少两份。不要把「一张卡既做 P 又做 D」还叫做分离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>请求进入 prefill 实例，只算提示、产首 token 与 KV，再把中间状态交给 decode 实例继续生成。Decode 计算利用率低时，可以多个 prefill 实例对应一个 decode 实例，让 decode 侧堆起更大的连续批，把带宽墙推向计算墙。资源搜索分两层：先在单副本上为两阶段分别选 GPU 数与并行策略，使每卡 goodput 最大；再用复制把该配比扩到目标流量。放置还要看集群带宽：跨节点 InfiniBand 足够时 P/D 可任意节点对；节点内 NVLink 强、跨节点弱时，要把对应层段放进同一节点，让 KV 走 NVLink（细节见 KV 传输篇）。</p><h3 id="splitwise-的异构池" tabindex="-1">Splitwise 的异构池 <a class="header-anchor" href="#splitwise-的异构池" aria-label="Permalink to &quot;Splitwise 的异构池&quot;">​</a></h3><p>Splitwise 的表征结论与 DistServe 一致：prompt 计算密集，generation 内存密集且往往吃不满最新 GPU 的算力。于是可以做同构拆分，也可以做异构：P 池用高算力卡，D 池用更便宜或更低功耗的卡。调度分集群级（请求进哪类机器）与机器级（批处理）。另设 mixed 池在突发时两阶段都能接，避免硬隔离导致一侧空、一侧炸。相对当时 colocate 设计，论文报告可达约 1.4 倍吞吐并降约 20% 成本，或在同样功耗与成本预算下约 2.35 倍吞吐。DistServe 正文把 Splitwise、TetriInfer、DéjàVu 列为同期分离工作，侧重点不同：DistServe 更强调双 SLO 下的 goodput 与带宽感知放置。</p>',15)),(o(),i(p,null,{default:a(()=>[d(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20P%5B%22Prefill%20%E6%B1%A0%EF%BC%9A%E7%AE%97%E5%8A%9B%E5%A2%99%EF%BC%8C%E4%BC%98%E5%8C%96%20TTFT%22%5D%0A%20%20P%20--%3E%20KV%5B%22%E4%BC%A0%E8%BE%93%20KV%20%2B%20%E9%A6%96%20token%22%5D%0A%20%20KV%20--%3E%20D%5B%22Decode%20%E6%B1%A0%EF%BC%9A%E5%B8%A6%E5%AE%BD%E5%A2%99%EF%BC%8C%E4%BC%98%E5%8C%96%20TPOT%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E6%B5%81%E5%BC%8F%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<h3 id="和-colocate-优化的边界" tabindex="-1">和 colocate 优化的边界 <a class="header-anchor" href="#和-colocate-优化的边界" aria-label="Permalink to &quot;和 colocate 优化的边界&quot;">​</a></h3><p>连续批、PagedAttention、GQA 在分离之后仍然需要：分离解决的是阶段干扰与并行耦合，不解决 KV 碎片或头数。Chunked-prefill 在分离后不再承担「保护 decode」的任务，仍可用于限制 prefill 激活。投机解码打在 decode 池上，<a href="/llm/spec-acceptance-rate">接受率</a> 与 decode batch 互动；prefill 池一般不跑草稿树。MoE 上 P/D 可取不同 <a href="/llm/infer-ep">EP</a> 度，这是分离送给稀疏模型的额外自由度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是<strong>消除时间轴上的互抢</strong>，以及<strong>解开并行搜索的笛卡尔积</strong>。Colocate 的每一步 iteration 里，prefill token 与 decode token 争 SM、争 HBM 带宽、争调度槽。拆开后，P 实例的迭代全是高算术强度，D 实例的迭代全是逐步 decode，CUDA Graph、并行度、甚至功耗帽都可以按阶段固定。代价是 KV 必须在阶段边界移动，且权重复制。当传输时间小于从前干扰造成的等待，goodput 上升；当传输是墙，分离失败——所以放置算法是方法的一部分，不是运维附属。</p>',4)),(o(),i(p,null,{default:a(()=>[d(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20COL%5B%22Colocate%EF%BC%9A%E5%90%8C%E4%B8%80%E5%BC%A0%E5%8D%A1%22%5D%0A%20%20%20%20C1%5B%22%E8%BF%9E%E7%BB%AD%E6%89%B9%E4%B8%80%E6%AD%A5%E6%B7%B7%E5%85%A5%E9%95%BF%20prefill%22%5D%20--%3E%20C2%5B%22decode%20%E6%AD%A5%E8%A2%AB%E6%8B%89%E9%95%BF%EF%BC%8CTPOT%20%E5%B0%96%E5%88%BA%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22decode%20%E5%8D%A0%E7%9D%80%20HBM%EF%BC%8Cprefill%20%E5%8F%88%E5%87%91%E4%B8%8D%E9%BD%90%E7%AE%97%E5%8A%9B%22%5D%0A%20%20end%0A%20%20subgraph%20DIS%5B%22%E5%88%86%E7%A6%BB%E5%90%8E%22%5D%0A%20%20%20%20D1%5B%22P%20%E5%AE%9E%E4%BE%8B%EF%BC%9A%E8%BF%AD%E4%BB%A3%E5%85%A8%E6%98%AF%E9%AB%98%E7%AE%97%E6%9C%AF%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20D2%5B%22%E9%98%B6%E6%AE%B5%E8%BE%B9%E7%95%8C%E6%90%AC%E4%B8%80%E6%AC%A1%20KV%22%5D%0A%20%20%20%20D2%20--%3E%20D3%5B%22D%20%E5%AE%9E%E4%BE%8B%EF%BC%9A%E6%89%B9%E5%A4%A7%E5%B0%8F%E4%B8%8E%E5%B9%B6%E8%A1%8C%E6%8C%89%20TPOT%20%E8%87%AA%E5%AE%9A%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">直觉类比：colocate 像一家餐厅让切菜师傅和服务员共用一张桌子——谁都干不顺；PD 分离是分成后厨和前厅，中间由传菜口（KV 传输）交接。传菜口太窄（互连太弱），上菜速度照样上不去，这就是「传输是墙则分离失败」。</span></p><p>Splitwise 再加一条：generation 不需要「最新 GPU 的峰值 FLOPs」，把新卡留给 prompt，能在集群功耗墙内提高总吞吐。这是硬件异构，不是算法异构。同构集群上 DistServe 的逻辑仍然成立。</p><p><span class="marginnote">TTFT 统计在分离后包含排队、prefill 执行与 KV 传输。若把传输算到 TPOT 里，SLO 归属会错，搜索机会往错误的池加卡。定义要在评测里写死。</span></p><h3 id="突发与排队" tabindex="-1">突发与排队 <a class="header-anchor" href="#突发与排队" aria-label="Permalink to &quot;突发与排队&quot;">​</a></h3><p>流量突发时，大量 KV 同时涌向 decode 会打满 D 侧显存。DistServe 用 pull：decode 按需来取，P 侧 GPU 内存当队列缓冲，两边各按自己的节奏跑。Splitwise 的 mixed 池是另一缓冲：暂时允许某台机器两阶段都做。没有这类阀门，分离系统会在峰值上比 colocate 更脆——colocate 至少「慢在同一张卡上」，分离会「D 侧 OOM、P 侧还在狂写」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>拆分的账单另一面是运维：预填充与解码各自扩缩、各自选并行策略，中间多一条 KV 传输链路和一类新故障。小流量、短提示、SLO 宽松的服务用同实例部署更简单；KV 体量巨大（超长上下文、未压缩 MHA）而互连带宽弱时，传输税会吞掉拆分收益——应先压 KV 或把两阶段放进同节点，再谈拆分。</p><p><span class="marginnote">常见误区：以为分离能省卡。实际上权重至少复制两份——P 池一份、D 池一份，卡数往往不降反升。分离买到的是达标速率（goodput）与延迟可控，不是省硬件；小模型、小流量上翻倍的权重账常让分离不划算。</span></p><p>不要把 PD 分离写成「P 用 CPU、D 用 GPU」或任意异构神话；Splitwise 的异构是 GPU 代数与功耗档，不是随便降级到不能跑模型的设备。不要伪造第三篇「PD 分离原论文」的 arXiv。可引用的就是 DistServe（arXiv:2401.09670）与 Splitwise（arXiv:2311.18677）。后续生产框架的实现以各自文档为准，性能数字随版本变。</p><p><span class="marginnote">评测必须同时报达标率、TTFT、TPOT、每 GPU 请求率。只报吞吐，分离看起来永远赢，因为可以把延迟藏在队列里。DistServe 用 goodput 就是为了堵住这条偷懒。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Prefill 与 decode 的 roofline、SLO、最优并行都不同；colocate 造成干扰并耦合资源配置。</li><li>DistServe 拆到不同实例，分阶段搜并行与复制，优化双 SLO 下的 goodput；报告约 7.4× 速率或约 12.6× 更紧 SLO。</li><li>Splitwise 强调阶段表征与异构/功耗，报告约 1.4× 吞吐降成本，或同预算约 2.35× 吞吐。</li><li>权重复制与 KV 传输是代价；放置与 pull 队列是方法，不是可选项。</li><li>小流量或弱互连上分离可能不划算；chunked-prefill 不能替代拆分。</li><li>出处：Zhong et al., <em>DistServe</em>，OSDI 2024，arXiv:2401.09670；Patel et al., <em>Splitwise</em>，ISCA 2024，arXiv:2311.18677。</li></ul>',12))])}const u=n(c,[["render",A]]);export{m as __pageData,u as default};
